#include <iostream>

int main()
{
    // Input temperature in Celsius
    double celsius = 35.0;

    // Logic error demonstration:
    // Integer division (9 / 5) evaluates to 1, producing an incorrect result (67)
    int incorrect_f = (9 / 5) * static_cast<int>(celsius) + 32;

    // Correct floating-point calculation:
    // Using 9.0 / 5.0 evaluates to 1.8, producing 95.0
    double correct_f = (9.0 / 5.0) * celsius + 32.0;

    std::cout << "Incorrect Fahrenheit: " << incorrect_f << std::endl;
    std::cout << "Correct Fahrenheit: " << correct_f << std::endl;

    return 0;
}
